#include <stdio.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return x - y;
}

int main(void) {
    int n, c[3];
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < 3; i++) scanf("%d", &c[i]);
    qsort(c, 3, sizeof(int), cmp);
    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (n >= c[i]) {
            n -= c[i];
            count++;
        } else {
            break;
        }
    }
    printf("%d\n", count);
    return 0;
}
